def match(orders):
    trades = []
    book_buy = []  # min heap by price (negated), then by arrival time: (-price, arrival_time, id, qty)
    book_sell = []  # min heap by price, then by arrival time: (price, arrival_time, id, qty)
    order_info = {}  # id -> {'side': 'buy'/'sell', 'qty': remaining_qty, 'price': price, 'cancelled': bool}
    arrival_time = 0

    for order in orders:
        arrival_time += 1

        if order[0] == 'cancel':
            order_id = order[1]
            if order_id in order_info:
                order_info[order_id]['cancelled'] = True
            continue

        order_type = order[0]
        order_id = order[1]
        side = order[2]
        qty = order[-1]
        price = order[3] if len(order) > 4 else None

        remaining_qty = qty

        if side == 'buy':
            # Match against resting sell orders
            while remaining_qty > 0 and book_sell:
                # Peek at best sell (lowest price, then earliest arrival)
                sell_price, sell_arrival, sell_id, sell_qty = book_sell[0]

                if order_type == 'market' or price >= sell_price:
                    if order_info[sell_id]['cancelled']:
                        book_sell.pop(0)
                        continue

                    trade_qty = min(remaining_qty, sell_qty)
                    trades.append([order_id, sell_id, sell_price, trade_qty])
                    remaining_qty -= trade_qty
                    order_info[sell_id]['qty'] -= trade_qty

                    if order_info[sell_id]['qty'] == 0:
                        book_sell.pop(0)
                    else:
                        book_sell[0] = (sell_price, sell_arrival, sell_id, order_info[sell_id]['qty'])
                else:
                    break

            # Add to book if not IOC/Market or if still has remaining qty (only limit orders rest)
            if order_type == 'limit' and remaining_qty > 0:
                order_info[order_id] = {'side': 'buy', 'qty': remaining_qty, 'price': price, 'cancelled': False}
                book_buy.append((-price, arrival_time, order_id, remaining_qty))
                book_buy.sort()

        else:  # side == 'sell'
            # Match against resting buy orders
            while remaining_qty > 0 and book_buy:
                # Peek at best buy (highest price, then earliest arrival)
                neg_buy_price, buy_arrival, buy_id, buy_qty = book_buy[0]
                buy_price = -neg_buy_price

                if order_type == 'market' or price <= buy_price:
                    if order_info[buy_id]['cancelled']:
                        book_buy.pop(0)
                        continue

                    trade_qty = min(remaining_qty, buy_qty)
                    trades.append([buy_id, order_id, buy_price, trade_qty])
                    remaining_qty -= trade_qty
                    order_info[buy_id]['qty'] -= trade_qty

                    if order_info[buy_id]['qty'] == 0:
                        book_buy.pop(0)
                    else:
                        book_buy[0] = (neg_buy_price, buy_arrival, buy_id, order_info[buy_id]['qty'])
                else:
                    break

            # Add to book if limit and still has remaining qty
            if order_type == 'limit' and remaining_qty > 0:
                order_info[order_id] = {'side': 'sell', 'qty': remaining_qty, 'price': price, 'cancelled': False}
                book_sell.append((price, arrival_time, order_id, remaining_qty))
                book_sell.sort()

    return trades

